) AS (
  VALUES 
    (543::BIGINT, 'Es un buen profe, solo que si de actitud es algo rodillo entonces sus comentarios o bromas no deben tomarsela a pecho, porque si nota que no le están cayendo bien el mae los va a joder con eso todo el semestre, lo bueno es que si explica como mejorar, de malas pero explica.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2026-07-16T00:00:00+00:00'::TIMESTAMPTZ, 'fdbd9d4fab45316e673f4732c23c4409bd8fc9e86e4f0ae21bcefaa3bb1a78e3'::TEXT, ARRAY[613]::BIGINT[]),
    (543::BIGINT, 'El peor profesor de lab de química II, agarra a los estudiantes entre ojos, los agarra como ejemplo como burla de la clase diciendo que esto es lo que no tienen q hacer, cuando te agarra entre ojos no le gusta absolutamente nada de lo que uno pone en los informes hace sentir mal y odiar lab'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2026-06-12T00:00:00+00:00'::TIMESTAMPTZ, '0b9aa7888c8d35178b1556d707e09bfed66ea24f052fbd10e33d76d1da1667b9'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (543::BIGINT, 'Demasiado buena gente, hace las clases sumamente interactivas y menos aburridas, siempre dispuesto ayudar, de fijo matricule con él'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2025-07-31T00:00:00+00:00'::TIMESTAMPTZ, '54584b2a8ef54dbce8236bbc5308a484ee73f760629cf4a1ddc85b186708dda9'::TEXT, ARRAY[568]::BIGINT[]),
    (543::BIGINT, 'Lo amo profe'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, '42dc184b7605eb9b85c93629344dc350594a02c57fcff2af9814484f36ebd706'::TEXT, ARRAY[568]::BIGINT[]),
    (543::BIGINT, 'Un profe que hace las clases entretenidas y fáciles, el material de estudio que entrega es resumido lo cual ayuda si solo quieres pasar la materia.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'cdb6fad8d93b9461dd0bf6dea8423e2e0ebd84aabf24a9ca2ad07f28ebbb37c0'::TEXT, ARRAY[568]::BIGINT[]),
    (543::BIGINT, 'Si eres alguien que aprende más con la práctica, el no es una opción ya que se la pasa leyendo las presentaciones y el favoritismo es algo presente'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura']::TEXT[], '2025-02-11T00:00:00+00:00'::TIMESTAMPTZ, '21677c73bdef8424510c9e6fb04104201c71383ce0c22a2d546be75171e73fa4'::TEXT, ARRAY[568]::BIGINT[]),
    (543::BIGINT, 'El profe es muy agradable y el material de la clase lo tiene ordenado. A veces lee de las presentaciones pero se le entiende muy bien. Califica justo y está pendiente a consultas.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-07-25T00:00:00+00:00'::TIMESTAMPTZ, 'f62e6f898a731715fe4a8581e7c621bef884c22085029327510f3e6edf87c3b6'::TEXT, ARRAY[3166, 3168]::BIGINT[]),
    (543::BIGINT, 'Uno de los profes que he tenido con más estima. Química I nunca me interesó mucho pero el hacía el curso muy entretenido y fácil. Deja varios quices, pero no eran muy difíciles, entonces usted iba preparado a los exámenes, en general es MUY buena nota con los estudiantes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-06-13T00:00:00+00:00'::TIMESTAMPTZ, '209bc483627468a026d32855df8a62c2177951482e57d69026be146542148a3f'::TEXT, ARRAY[568]::BIGINT[]),
    (543::BIGINT, 'Es el mejor profe que puede existir, si a usted no le interesa la química, con este profe le va a encantar, hace que los temas sean muy interesantes y entretenidos.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-02-25T00:00:00+00:00'::TIMESTAMPTZ, 'd1e897e16efe18fe3f56e2a6cc424051c977dc0e131935119b4337bc38b68a02'::TEXT, ARRAY[568]::BIGINT[]),
    (543::BIGINT, 'La verdad el profe es un amor, explica muy ordenado, te prepara para los exámenes, los exámenes cortos hace bastantes pero eso te ayuda al final para nota, algunos son muy fáciles, otros no tanto, pero se pasa muy relajado. Recomendado'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-03T00:00:00+00:00'::TIMESTAMPTZ, '52e42c9b0912ae26daead61eb466f091c21f1035fa609462dc95d316b7b04a85'::TEXT, ARRAY[613]::BIGINT[]),
    (543::BIGINT, 'Profe te amo'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-10-31T00:00:00+00:00'::TIMESTAMPTZ, '7d614bcf8c55288beab65320a42fcba88ff4dd2f239f819dce190115e375b84f'::TEXT, ARRAY[573]::BIGINT[]),
    (543::BIGINT, 'El m4e es buena nota y sí sabe lo que habla, aunque sí tiene cambios de humor raros, osea puede llegar amargado a clase o puede llegar regalando flores; tiene vocación y es muy bueno explicando y ayudando (y es pura PP todo), aunque también tiene sus preferidos, so pulsee para estar entre esos.'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Clases largas']::TEXT[], '2023-08-05T00:00:00+00:00'::TIMESTAMPTZ, '3692eb73a8c94dfd2637615c790e887d9f408836ccea9ad67a5698a57df16491'::TEXT, ARRAY[568]::BIGINT[]),
    (543::BIGINT, 'El profe lo prepara a uno demasiado bien para los exámenes que son de cátedra. Los quizzes los revisa un toque duro, pero al final a uno le va bien en los exámenes gracias a eso'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Inspirador']::TEXT[], '2023-06-27T00:00:00+00:00'::TIMESTAMPTZ, '204194fd022b1efc69545c83c165df597566218499f95ff01de8c8f819c91f7d'::TEXT, ARRAY[568]::BIGINT[]),
    (543::BIGINT, 'Muy buen profe, califica un toque duro los informes pero siempre está dispuesto a ayudarlo a uno cuando no logra entender algo'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'f1c95aa029afc769e1ca83d9ceccbd513c1758c6068b25457842d5500e4f58e1'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (543::BIGINT, 'Es muy buen profe, explica muy bien y llegando a los exámenes hace repasos y prácticas sobre todo lo que entra, busca qué todos los estudiantes entiendan y brinda mucho apoyo. Si pueden matriculen con él, la clase se hace corta de lo interesante que es, hace quiz extra para ayudar a subir la nota.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '7d6cfd4ac4d06ad3d82c8b04eddc68366f85ecaf0d9e547ac928caa4b506dbca'::TEXT, ARRAY[568]::BIGINT[]),
    (543::BIGINT, 'Califica duro y tienes que prestar mucha atención en cada cosa que dice, me parece que su forma de explicar no es tan buena y su personalidad es pasivo-agresivo, así que hay que tener mucho cuidado con eso. Sin embargo, es muy buen profesor y si vos ocupas entender algo él te lo explica.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Exámenes retadores']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '437feb4abd2a35e7d7821645f527284368ce6765ef33ae2e7d50d821b6a25fc9'::TEXT, ARRAY[567, 3167, 3169]::BIGINT[]),
    (543::BIGINT, 'El profe es jóven por lo que entiende mucho al estudiante y vacila con todos, no hace la clase aburrida. No le de pena preguntar algo que no le quede claro porque él se lo explica hasta que entienda, muy amable. Hace quiz extra para ayudar con la nota y explica bien. ¡Si pueden matriculen con él!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'fdd0ad5df28bb88498612a3564675aa941b8810056c1b564846d6ce6d980a7a4'::TEXT, ARRAY[568]::BIGINT[]),
    (543::BIGINT, 'EL MEJOR PROFE DE LA FAZ DE LA TIERRA, HAGASE UN FAVOR Y MATRICULE CON ÉL'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'ea83fb2ed6d47100b2723ceea677cb9eea65959e582e7d66950e42f5701d4012'::TEXT, ARRAY[573]::BIGINT[]),
    (543::BIGINT, 'Profe muy interesado en que sus estudiantes aprendan y aprueben. Muy buena gente y excelentes clases.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-05-24T00:00:00+00:00'::TIMESTAMPTZ, '59e350437052e0cfee7eff144b96d5b1ffabcd7cc1bc310180177da35a622dbe'::TEXT, ARRAY[568]::BIGINT[]),
    (543::BIGINT, 'Es un profe joven por lo que socializar con los estudiantes le es muy fácil, es un muy buen profesor y sus explicaciones son muy claras, brinda apoyo con cualquier duda que tengas sobre algún procedimiento o alguna duda de la teoría'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2023-01-30T00:00:00+00:00'::TIMESTAMPTZ, '425a57b2aba7c5fc6ad9bb3ebd1df5b072dd4524dcf4acdead368e7fc1a1a1f5'::TEXT, ARRAY[613, 3167, 3169]::BIGINT[]),
    (543::BIGINT, 'Muy buen profe, explica super bien, es como estar con un compañero más, los quices algunos son durillos, pero por lo general super recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'a3f074efa73a0a4f1cb2b2901c6ec19211add3e6f4163f9003553891c13ffd4b'::TEXT, ARRAY[613, 3167, 3169]::BIGINT[]),
    (543::BIGINT, 'El profe de verdad es excelente en todo sentido. Explica súper bien y los laboratorios los hace muy amenos, uno realmente los disfruta la clase y aprende. Siempre está atento a las dudas y en serio es una increíble persona. Mega recomendado:))'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, '0edd70f26952c244b58a2772230eade4f8d7a09f36fb0d0b7ccad73fb971091b'::TEXT, ARRAY[613, 3167, 3169]::BIGINT[]),
    (543::BIGINT, 'Muy buen profe, diría que el mejor que hay para lab explica muy bien y las veces que sean necesarias, ayuda mucho'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-13T00:00:00+00:00'::TIMESTAMPTZ, '67bdc1bbbb395cc09f9e27b9fdd120262aeaaafde3ba275fda9a5947a12102f2'::TEXT, ARRAY[613, 3167, 3169]::BIGINT[]),
    (543::BIGINT, 'El profe es súper joven, pero no lo menosprecien por eso. Él es EXCELENTE. Explica súper bien, es demasiado organizados con el TecDigital y las evaluaciones, responde consultas por Teams, hace reuniones por zoom y los quices son muuuuy fáciles. De verdad matriculen con él, califica suave los informe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'f510a4b3cc0f52b4c59ed0b693ddb72d52912b7292be280f39f70231b46de163'::TEXT, ARRAY[613, 3167, 3169]::BIGINT[]),
    (543::BIGINT, 'Yo solo recomiendo un profe cuando es EXCELENTE, y este lo es en todo sentido. En Lab es el mejor que hay, si fuera por mí lo pondría a dar teoría sin pensarlo ya que es de el mejor explicando. Cuando usted lo ve piensa que es un compañero suyo o a lo mucho un asistente porque es demasiado jovenJAJA'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '8e6e2b1a803a37e8ca10db73e36de8c991c996a21ae268ac8d67076c40ec9136'::TEXT, ARRAY[613, 3167, 3169]::BIGINT[]),
    (543::BIGINT, 'Excelente profe. Explica de forma clara, resuelve dudas las veces que sean necesarias. Es simpático, las clases eran interesantes.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '53fd4affa34a447174cd1dbf6b8bb16e582b527d3dbcd99dc2f09e097e949fef'::TEXT, ARRAY[613]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
